    kpi_card(k3, "Net Profit",     f"KES {net_profit:,.0f}",     "revenue minus expenses",      "orange")
    kpi_card(k4, "Profit Margin",  f"{margin_pct:.1f}%",          "net ÷ revenue",               "blue")

